def calculate_ratio(x, y, z):
    lhs = (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1)
    denominator = x*y + y*z + z*x
    if denominator == 0:
        return None # Should not happen for positive reals
    return lhs / denominator

cases = {
    " (2, 1, 1)": (2, 1, 1),
    " (2, 2, 1)": (2, 2, 1),
    " (3, 1, 1)": (3, 1, 1)
}

results = {}
for label, (x, y, z) in cases.items():
    ratio = calculate_ratio(x, y, z)
    results[label] = ratio

print("Calculated Ratios:")
for label, ratio in results.items():
    print(f"Ratio for{label}: {ratio}")
